// src/components/ComplexTextEditor/Toolbars/Editor/index.tsx

'use client'
import React, { useState, useEffect, useRef, useCallback } from 'react'
import Dropdown from '../../../Field/Dropdown/Regular'
import CustomButton from '../../../Button'
import {
  handleBoldClick as markdownBoldClick,
  handleItalicClick as markdownItalicClick,
  replaceSelectedText,
} from '../../utils/useMarkdownEditor'
import type { ComplexTextEditorStyles } from '../../theme'
import cssStyles from '../../ComplexTextEditor.module.css'

import LinkIcon from '../../../Icons/Link'
import UndoIcon from '../../../Icons/Undo'
import RedoIcon from '../../../Icons/Redo'
import FormatAlignLeftIcon from '../../../Icons/FormatAlignLeft'
import FormatAlignCenterIcon from '../../../Icons/FormatAlignCenter'
import FormatAlignRightIcon from '../../../Icons/FormatAlignRight'
import FormatBoldIcon from '../../../Icons/FormatBold'
import FormatItalicIcon from '../../../Icons/FormatItalic'
import FormatUnderlinedIcon from '../../../Icons/FormatUnderlined'
import StrikethroughSIcon from '../../../Icons/StrikethroughS'
import CodeIcon from '../../../Icons/Code'
import FormatListNumberedIcon from '../../../Icons/FormatListNumbered'
import FormatListBulletedIcon from '../../../Icons/FormatListBulleted'

// Inlined from the goobs palette (theme/index.ts) so this toolbar no longer
// imports from src/theme. These drive the active-button `styles` prop fed to
// the goobs Button component — a runtime value computed from
// document.queryCommandState, so it legitimately stays in JS.
const BLACK_MAIN = '#000000' // black.main
const GREY_DARK = '#BDBDBD' // grey.dark

// --------------------------------------------------------------------------
// TOOLBAR COMPONENT INTERFACE
// --------------------------------------------------------------------------

// Define types directly in this file that aren't already imported
export type TextType = 'paragraph' | 'h1' | 'h2' | 'h3'
export type AlignmentFormat = 'left' | 'center' | 'right' | 'justify'

interface ToolbarMarkdownProps {
  editor?: any // Slate editor
  handleBoldClick?: () => void
  handleItalicClick?: () => void
  handleUnderlineClick?: () => void
  handleStrikethroughClick?: () => void
  handleCodeClick?: () => void
  handleLinkClick?: () => void

  handleUndo?: () => void
  handleRedo?: () => void
  handleAlign?: (align: string) => void
  handleTextType?: (type: string) => void
  handleBulletedList?: () => void
  handleNumberedList?: () => void
  markdownMode: boolean
  setMarkdown: (value: string) => void
  toolbarType?: 'markdown' | 'richtext' | 'rich'
  styles?: ComplexTextEditorStyles
  /**
   * Caller-override CSS-variable object (--ct-toolbar-bg / --ct-toolbar-padding
   * / --ct-toolbar-gap) applied inline on the toolbar wrapper so
   * toolbarBackground / toolbarPadding / toolbarGap are honored as in the old
   * getComplexTextEditorTheme toolbar branch.
   */
  wrapperStyle?: React.CSSProperties
}

// --------------------------------------------------------------------------
// STYLE CONFIGURATIONS — layout containers migrated to ComplexTextEditor.module.css
// (.toolbarContainer / .toolbarRow / .primaryRow / .dropdownRow / .buttonGroup /
// .toolbarDropdown). The sacred translucent backdrop is the
// .toolbarContainer[data-theme='sacred'] override.
// --------------------------------------------------------------------------

const ToolbarMarkdown: React.FC<ToolbarMarkdownProps> = ({
  editor,
  handleBoldClick,
  handleItalicClick,
  handleUnderlineClick,
  handleStrikethroughClick,
  handleCodeClick,
  handleLinkClick,

  handleUndo,
  handleRedo,
  handleAlign,
  handleTextType,
  handleBulletedList,
  handleNumberedList,
  markdownMode,
  setMarkdown,
  toolbarType = 'richtext',
  styles,
  wrapperStyle,
}) => {
  const [alignValue, setAlignValue] = useState<AlignmentFormat>('left')
  const [textType, setTextType] = useState<TextType>('paragraph')

  const isSacredTheme = styles?.theme === 'sacred'

  // Display additional tool options based on toolbar type
  const showExtendedOptions = toolbarType === 'richtext' && !markdownMode

  const handleAlignChange = (value: string) => {
    setAlignValue(value as AlignmentFormat)
  }

  const handleTextTypeChange = (value: string) => {
    const newType = value as TextType
    setTextType(newType)
    if (handleTextType) {
      handleTextType(newType)
    }
  }

  const textTypeOptions = [
    { value: 'paragraph' },
    { value: 'h1' },
    { value: 'h2' },
    { value: 'h3' },
  ]

  const alignmentOptions = [
    {
      value: 'left',
      icon: (
        <FormatAlignLeftIcon
          styles={{ theme: styles?.theme || 'sacred', size: 16 }}
        />
      ),
    },
    {
      value: 'center',
      icon: (
        <FormatAlignCenterIcon
          styles={{ theme: styles?.theme || 'sacred', size: 16 }}
        />
      ),
    },
    {
      value: 'right',
      icon: (
        <FormatAlignRightIcon
          styles={{ theme: styles?.theme || 'sacred', size: 16 }}
        />
      ),
    },
  ]

  const handleEditorAction =
    (action: string) => (event: React.MouseEvent<HTMLButtonElement>) => {
      event.preventDefault()

      // Handle markdown mode actions
      if (markdownMode) {
        const selection = window.getSelection()
        if (selection) {
          const selectedText = selection.toString()

          switch (action) {
            case 'bold':
              if (handleBoldClick) {
                handleBoldClick()
              } else {
                markdownBoldClick(selectedText, selectedText, setMarkdown)
              }
              break

            case 'italic':
              if (handleItalicClick) {
                handleItalicClick()
              } else {
                markdownItalicClick(selectedText, selectedText, setMarkdown)
              }
              break

            case 'code':
              if (selectedText) {
                const newValue = '`' + selectedText + '`'
                replaceSelectedText(
                  newValue,
                  selectedText,
                  selectedText,
                  setMarkdown
                )
              }
              break

            case 'link': {
              const url = prompt('Enter the URL')
              if (url && selectedText) {
                const newValue = '[' + selectedText + '](' + url + ')'
                replaceSelectedText(
                  newValue,
                  selectedText,
                  selectedText,
                  setMarkdown
                )
              }
              break
            }

            case 'strikethrough':
              if (selectedText) {
                const newValue = '~~' + selectedText + '~~'
                replaceSelectedText(
                  newValue,
                  selectedText,
                  selectedText,
                  setMarkdown
                )
              }
              break

            case 'bulleted-list':
              if (selectedText) {
                // Split by lines and add bullets
                const lines = selectedText.split('\n')
                const bulletedList = lines.map(line => `* ${line}`).join('\n')
                replaceSelectedText(
                  bulletedList,
                  selectedText,
                  selectedText,
                  setMarkdown
                )
              }
              break

            case 'numbered-list':
              if (selectedText) {
                // Split by lines and add numbers
                const lines = selectedText.split('\n')
                const numberedList = lines
                  .map((line, index) => `${index + 1}. ${line}`)
                  .join('\n')
                replaceSelectedText(
                  numberedList,
                  selectedText,
                  selectedText,
                  setMarkdown
                )
              }
              break

            case 'undo':
            case 'redo':
            case 'underline':
              // These might not be supported in basic markdown
              break
          }
        }
      }
      // Handle rich text editor actions
      else if (editor) {
        switch (action) {
          case 'undo':
            if (handleUndo) {
              handleUndo()
            }
            break

          case 'redo':
            if (handleRedo) {
              handleRedo()
            }
            break

          case 'bulleted-list':
            if (handleBulletedList) {
              handleBulletedList()
            }
            break

          case 'numbered-list':
            if (handleNumberedList) {
              handleNumberedList()
            }
            break

          case 'left':
            if (handleAlign) {
              handleAlign('left')
            }
            break

          case 'center':
            if (handleAlign) {
              handleAlign('center')
            }
            break

          case 'right':
            if (handleAlign) {
              handleAlign('right')
            }
            break

          case 'justify':
            if (handleAlign) {
              handleAlign('justify')
            }
            break

          case 'bold':
            if (handleBoldClick) {
              handleBoldClick()
            }
            break

          case 'italic':
            if (handleItalicClick) {
              handleItalicClick()
            }
            break

          case 'underline':
            if (handleUnderlineClick) {
              handleUnderlineClick()
            }
            break

          case 'strikethrough':
            if (handleStrikethroughClick) {
              handleStrikethroughClick()
            }
            break

          case 'code':
            if (handleCodeClick) {
              handleCodeClick()
            }
            break

          case 'link':
            if (handleLinkClick) {
              handleLinkClick()
            }
            break
        }
      }
    }

  // Live formatting state for the rich-text toggle buttons. The old code gated
  // this on a Slate `editor` object this component is never handed, so the
  // active state (and any aria-pressed derived from it) was permanently dead.
  // Rich mode drives formatting through document.execCommand, so
  // document.queryCommandState IS the source of truth — tracked on the client
  // via `selectionchange` so both the visual active state and the buttons'
  // aria-pressed stay truthful as the caret/selection moves. Guarded to the
  // client (effect) + wrapped in try/catch so SSR and unsupported commands
  // never throw.
  const [activeFormats, setActiveFormats] = useState<Record<string, boolean>>(
    {}
  )
  useEffect(() => {
    if (markdownMode) return
    // Map the toolbar's format keys to their execCommand query names.
    const queryCommandMap: Record<string, string> = {
      bold: 'bold',
      italic: 'italic',
      underline: 'underline',
      strikethrough: 'strikeThrough',
      'numbered-list': 'insertOrderedList',
      'bulleted-list': 'insertUnorderedList',
    }
    const readState = () => {
      const next: Record<string, boolean> = {}
      for (const [format, command] of Object.entries(queryCommandMap)) {
        try {
          next[format] = document.queryCommandState(command)
        } catch {
          next[format] = false
        }
      }
      setActiveFormats(next)
    }
    readState()
    document.addEventListener('selectionchange', readState)
    return () => document.removeEventListener('selectionchange', readState)
  }, [markdownMode])

  // Whether a toggle format is currently applied at the selection. Markdown
  // mode has no persistent format state (its buttons wrap the selection), so it
  // always reports false and those buttons are exposed as command buttons.
  const isFormatActive = (format: string): boolean => {
    if (markdownMode) return false
    return activeFormats[format] ?? false
  }

  // Toggle-capable formats get aria-pressed (WAI-ARIA toggle button); the rest
  // (undo / redo / link / code) are plain command buttons. Every icon-only
  // button also gets an aria-label so it has an accessible name (WCAG 4.1.2).
  const TOGGLE_FORMATS = new Set([
    'bold',
    'italic',
    'underline',
    'strikethrough',
    'numbered-list',
    'bulleted-list',
  ])
  const getButtonA11y = (
    format: string,
    accessibleName: string
  ): React.AriaAttributes => ({
    'aria-label': accessibleName,
    ...(!markdownMode && TOGGLE_FORMATS.has(format)
      ? { 'aria-pressed': isFormatActive(format) }
      : {}),
  })

  // Layout containers are CSS classes; the sacred backdrop is a
  // [data-theme='sacred'] override on .toolbarContainer.
  const toolbarTheme = styles?.theme || 'light'

  // Create button styles for the unified theme system
  const getButtonStyles = (format: string) => {
    const isActive = isFormatActive(format)

    return {
      theme: styles?.theme || 'light',
      backgroundColor: isActive
        ? isSacredTheme
          ? 'var(--goobs-gold-a20)'
          : 'var(--goobs-black-a10)'
        : 'transparent',
      color: isActive
        ? isSacredTheme
          ? 'var(--goobs-gold)'
          : GREY_DARK
        : isSacredTheme
          ? 'var(--goobs-gold-a80)'
          : BLACK_MAIN,
      borderRadius: '2px',
      minWidth: '36px',
      width: '36px',
      height: '36px',
      padding: '6px',
      margin: '2px',
    }
  }

  // ---- WAI-ARIA APG Toolbar keyboard pattern (roving tabindex) ------------
  // `role="toolbar"` sets an AT expectation that the whole control row is a
  // SINGLE Tab stop navigated with the Arrow keys. We implement that: exactly
  // one control is tabbable (tabIndex 0); the rest are tabIndex -1 and reached
  // with Left/Right Arrow + Home/End. The set is discovered live from the DOM
  // (every enabled <button> — the icon buttons AND the rich-text-only dropdown
  // comboboxes) so it stays correct as rows and disabled states mount/unmount.
  // All of this runs only on the client (refs + event handlers), so it is
  // SSR-safe. Basic Enter/Space activation is unchanged (native button).
  const toolbarRef = useRef<HTMLDivElement>(null)

  const getToolbarControls = useCallback((): HTMLElement[] => {
    const root = toolbarRef.current
    if (!root) return []
    return Array.from(root.querySelectorAll<HTMLElement>('button')).filter(
      el =>
        !(el as HTMLButtonElement).disabled &&
        // exclude an open combobox's own portalled/inline option buttons
        el.getAttribute('role') !== 'option'
    )
  }, [])

  // Make exactly one control tabbable. `preferred` keeps the roved position
  // when it's still in the set; otherwise the first control becomes the stop.
  const applyRovingTabIndex = useCallback(
    (preferred: HTMLElement | null) => {
      const controls = getToolbarControls()
      if (controls.length === 0) return
      const active =
        preferred && controls.includes(preferred) ? preferred : controls[0]
      controls.forEach(el => {
        el.tabIndex = el === active ? 0 : -1
      })
    },
    [getToolbarControls]
  )

  // (Re)initialize the single tab stop whenever the control set changes: the
  // mode switch toggles disabled buttons and the dropdown row is rich-only.
  useEffect(() => {
    applyRovingTabIndex(null)
  }, [applyRovingTabIndex, markdownMode, showExtendedOptions])

  const handleToolbarKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      const { key } = event
      if (
        key !== 'ArrowLeft' &&
        key !== 'ArrowRight' &&
        key !== 'Home' &&
        key !== 'End'
      ) {
        return
      }
      // A contained combobox owns its own Arrow/Home/End navigation while it
      // is open — don't hijack those keys then.
      const focused = document.activeElement as HTMLElement | null
      if (focused?.getAttribute('aria-expanded') === 'true') return
      const controls = getToolbarControls()
      if (controls.length === 0) return
      const currentIndex = focused ? controls.indexOf(focused) : -1
      let nextIndex: number
      switch (key) {
        case 'ArrowRight':
          nextIndex =
            currentIndex < 0 ? 0 : (currentIndex + 1) % controls.length
          break
        case 'ArrowLeft':
          nextIndex = currentIndex <= 0 ? controls.length - 1 : currentIndex - 1
          break
        case 'Home':
          nextIndex = 0
          break
        default: // 'End'
          nextIndex = controls.length - 1
          break
      }
      const next = controls[nextIndex]
      if (!next) return
      event.preventDefault()
      controls.forEach(el => {
        el.tabIndex = el === next ? 0 : -1
      })
      next.focus()
    },
    [getToolbarControls]
  )

  // Keep the tab stop on whichever control the user focuses (e.g. by mouse) so
  // Shift+Tab back into the toolbar returns to the last-used control.
  const handleToolbarFocus = useCallback(
    (event: React.FocusEvent<HTMLDivElement>) => {
      applyRovingTabIndex(event.target as HTMLElement)
    },
    [applyRovingTabIndex]
  )

  return (
    <div
      ref={toolbarRef}
      className={cssStyles.toolbarContainer}
      data-theme={toolbarTheme}
      role="toolbar"
      aria-label={markdownMode ? 'Markdown formatting' : 'Text formatting'}
      onKeyDown={handleToolbarKeyDown}
      onFocus={handleToolbarFocus}
      {...(styles?.showToolbar === false && { 'data-hidden': 'true' })}
      {...(wrapperStyle && { style: wrapperStyle })}
    >
      {/* Row 1: Primary Actions - Undo/Redo + Essential Formatting */}
      <div className={cssStyles.primaryRow}>
        {/* undo / redo */}
        <div className={cssStyles.buttonGroup}>
          <CustomButton
            icon={
              <UndoIcon
                aria-hidden="true"
                styles={{ theme: styles?.theme || 'sacred', size: 16 }}
              />
            }
            onClick={handleEditorAction('undo')}
            styles={getButtonStyles('undo')}
            disabled={markdownMode}
            {...getButtonA11y('undo', 'Undo')}
          />
          <CustomButton
            icon={
              <RedoIcon
                aria-hidden="true"
                styles={{ theme: styles?.theme || 'sacred', size: 16 }}
              />
            }
            onClick={handleEditorAction('redo')}
            styles={getButtonStyles('redo')}
            disabled={markdownMode}
            {...getButtonA11y('redo', 'Redo')}
          />
        </div>

        {/* Essential formatting buttons */}
        <div className={cssStyles.buttonGroup}>
          <CustomButton
            icon={
              <FormatBoldIcon
                aria-hidden="true"
                styles={{ theme: styles?.theme || 'sacred', size: 16 }}
              />
            }
            onClick={handleEditorAction('bold')}
            styles={getButtonStyles('bold')}
            {...getButtonA11y('bold', 'Bold')}
          />
          <CustomButton
            icon={
              <FormatItalicIcon
                aria-hidden="true"
                styles={{ theme: styles?.theme || 'sacred', size: 16 }}
              />
            }
            onClick={handleEditorAction('italic')}
            styles={getButtonStyles('italic')}
            {...getButtonA11y('italic', 'Italic')}
          />
          <CustomButton
            icon={
              <FormatUnderlinedIcon
                aria-hidden="true"
                styles={{ theme: styles?.theme || 'sacred', size: 16 }}
              />
            }
            onClick={handleEditorAction('underline')}
            styles={getButtonStyles('underline')}
            disabled={markdownMode}
            {...getButtonA11y('underline', 'Underline')}
          />
        </div>
      </div>

      {/* Row 2: Dropdowns - Text Type & Alignment (only in rich text mode) */}
      {showExtendedOptions && (
        <div className={cssStyles.dropdownRow}>
          <div className={cssStyles.toolbarDropdown}>
            <Dropdown
              label="Text Type"
              options={textTypeOptions}
              value={textType}
              onChange={handleTextTypeChange}
              styles={{ theme: styles?.theme || 'light' }}
            />
          </div>
          <div className={cssStyles.toolbarDropdown}>
            <Dropdown
              label="Alignment"
              options={alignmentOptions}
              value={alignValue}
              onChange={handleAlignChange}
              styles={{ theme: styles?.theme || 'light' }}
            />
          </div>
        </div>
      )}

      {/* Row 3: Secondary Formatting & Structure */}
      <div className={cssStyles.toolbarRow}>
        <div className={cssStyles.buttonGroup}>
          <CustomButton
            icon={
              <StrikethroughSIcon
                aria-hidden="true"
                styles={{ theme: styles?.theme || 'sacred', size: 16 }}
              />
            }
            onClick={handleEditorAction('strikethrough')}
            styles={getButtonStyles('strikethrough')}
            {...getButtonA11y('strikethrough', 'Strikethrough')}
          />
          <CustomButton
            icon={
              <CodeIcon
                aria-hidden="true"
                styles={{ theme: styles?.theme || 'sacred', size: 16 }}
              />
            }
            onClick={handleEditorAction('code')}
            styles={getButtonStyles('code')}
            {...getButtonA11y('code', 'Code')}
          />
          <CustomButton
            icon={
              <LinkIcon
                aria-hidden="true"
                styles={{ theme: styles?.theme || 'sacred', size: 16 }}
              />
            }
            onClick={handleEditorAction('link')}
            styles={getButtonStyles('link')}
            {...getButtonA11y('link', 'Insert link')}
          />
        </div>

        <div className={cssStyles.buttonGroup}>
          <CustomButton
            icon={
              <FormatListNumberedIcon
                aria-hidden="true"
                styles={{ theme: styles?.theme || 'sacred', size: 16 }}
                style={{ width: '16px', height: '16px' }}
              />
            }
            onClick={handleEditorAction('numbered-list')}
            styles={getButtonStyles('numbered-list')}
            {...getButtonA11y('numbered-list', 'Numbered list')}
          />
          <CustomButton
            icon={
              <FormatListBulletedIcon
                aria-hidden="true"
                styles={{ theme: styles?.theme || 'sacred', size: 16 }}
                style={{ width: '16px', height: '16px' }}
              />
            }
            onClick={handleEditorAction('bulleted-list')}
            styles={getButtonStyles('bulleted-list')}
            {...getButtonA11y('bulleted-list', 'Bulleted list')}
          />
        </div>
      </div>
    </div>
  )
}

export default ToolbarMarkdown
